Generate 40 test inputs for the following source code. The code reads from standard input and writes to standard output.
The test inputs should cover various parts of the input space, including corner cases.
The source code should successfully run with each given test input and print an output in a reasonable amount of time (less than 5 seconds), with no runtime error.
Follow the input format described in the input specification and the sample inputs.

Print every test input in the following format:
<test_inputs>
<input>
<test input>
</input>
<input>
<test input>
</input>
</test_inputs>
Do not provide any other text or markdown fences.

Here is the problem description:
<description>
Integers from $$$1$$$ to $$$n$$$ (inclusive) were sorted lexicographically (considering integers as strings). As a result, array $$$a_1, a_2, \dots, a_n$$$ was obtained.Calculate value of $$$(\sum_{i = 1}^n ((i - a_i) \mod 998244353)) \mod 10^9 + 7$$$.$$$x \mod y$$$ here means the remainder after division $$$x$$$ by $$$y$$$. This remainder is always non-negative and doesn't exceed $$$y - 1$$$. For example, $$$5 \mod 3 = 2$$$, $$$(-1) \mod 6 = 5$$$. 
</description>

Here is the input specification:
<input_spec>
The first line contains the single integer $$$n$$$ ($$$1 \leq n \leq 10^{12}$$$).
</input_spec>

Here are additional notes:
<notes>
NoteA string $$$a$$$ is lexicographically smaller than a string $$$b$$$ if and only if one of the following holds:  $$$a$$$ is a prefix of $$$b$$$, but $$$a \ne b$$$;  in the first position where $$$a$$$ and $$$b$$$ differ, the string $$$a$$$ has a letter that appears earlier in the alphabet than the corresponding letter in $$$b$$$. For example, $$$42$$$ is lexicographically smaller than $$$6$$$, because they differ in the first digit, and $$$4 &lt; 6$$$; $$$42 &lt; 420$$$, because $$$42$$$ is a prefix of $$$420$$$.Let's denote $$$998244353$$$ as $$$M$$$.In the first example, array $$$a$$$ is equal to $$$[1, 2, 3]$$$.   $$$(1 - 1) \mod M = 0 \mod M = 0$$$  $$$(2 - 2) \mod M = 0 \mod M = 0$$$  $$$(3 - 3) \mod M = 0 \mod M = 0$$$ As a result, $$$(0 + 0 + 0) \mod 10^9 + 7 = 0$$$In the second example, array $$$a$$$ is equal to $$$[1, 10, 11, 12, 2, 3, 4, 5, 6, 7, 8, 9]$$$.   $$$(1 - 1) \mod M = 0 \mod M = 0$$$  $$$(2 - 10) \mod M = (-8) \mod M = 998244345$$$  $$$(3 - 11) \mod M = (-8) \mod M = 998244345$$$  $$$(4 - 12) \mod M = (-8) \mod M = 998244345$$$  $$$(5 - 2) \mod M = 3 \mod M = 3$$$  $$$(6 - 3) \mod M = 3 \mod M = 3$$$  $$$(7 - 4) \mod M = 3 \mod M = 3$$$  $$$(8 - 5) \mod M = 3 \mod M = 3$$$  $$$(9 - 6) \mod M = 3 \mod M = 3$$$  $$$(10 - 7) \mod M = 3 \mod M = 3$$$  $$$(11 - 8) \mod M = 3 \mod M = 3$$$  $$$(12 - 9) \mod M = 3 \mod M = 3$$$ As a result, $$$(0 + 998244345 + 998244345 + 998244345 + 3 + 3 + 3 + 3 + 3 + 3 + 3 + 3) \mod 10^9 + 7$$$ $$$=$$$ $$$2994733059 \mod 10^9 + 7$$$ $$$=$$$ $$$994733045$$$
</notes>

Here are sample inputs:
<sample_inputs>
<input>
3
</input>
<input>
12
</input>
<input>
21
</input>
<input>
1000000000000
</input>
</sample_inputs>

Here is the source code:
<source_code>
#include <bits/stdc++.h>

using namespace std;

# define Rep(i,a,b) for(int i=a;i<=b;i++)
# define _Rep(i,a,b) for(int i=a;i>=b;i--)
# define RepG(i,u) for(int i=head[u];~i;i=e[i].next)

const int N=1e6+5;
const int mod1=998244353;
const int mod2=1e9+7;
const int base=1000000;

typedef long long ll;
typedef double db;

# define chkmax(a,b) a=max(a,b)
# define chkmin(a,b) a=min(a,b)
# define PII pair<int,int>
# define mkp make_pair

template<typename T> void read(T &x){
    x=0;int f=1;
    char c=getchar();
    for(;!isdigit(c);c=getchar())if(c=='-')f=-1;
    for(;isdigit(c);c=getchar())x=(x<<1)+(x<<3)+c-'0';
    x*=f;
}

ll n;
vector<int> v[10];
ll gg;
int sum[10];
int ans;

void dfs1(int u,int x){
    v[u].push_back(((++gg)-x+mod1)%mod1),sum[u]+=v[u].back()%mod2,sum[u]%=mod2;
    if(u==6)return;
    Rep(i,0,9)dfs1(u+1,10*x+i);
}

void dfs2(ll x){
    if(x>n)return;
    if(x*base+base-1<=n&&x*base*10>n){
        ll rk=gg;
        for(int i=0,bit=1;i<=6;i++,bit*=10){
            int mae=((rk-x*bit)%mod1+mod1)%mod1;
            int pos=lower_bound(v[i].begin(),v[i].end(),-mae+mod1)-v[i].begin();
            // printf("%d\n",pos);
            ans+=((1ll*mae*v[i].size()%mod2+sum[i])%mod2-1ll*(v[i].size()-pos)*mod1%mod2+mod2)%mod2;
            ans%=mod2;
            // printf("%d\n",ans);
            gg+=v[i].size();
        }   
        return;
    }
    ans+=(((++gg)-x)%mod1+mod1)%mod1,ans%=mod2;
    Rep(i,0,9)dfs2(x*10+i);
}

int main()
{
    # ifdef YuukiYumesaki
    freopen("testdata.in","r",stdin);
    freopen("test1.out","w",stdout);
    # endif
    read(n);
    dfs1(0,0);
    Rep(i,0,6)sort(v[i].begin(),v[i].end());
    gg=0;
    Rep(i,1,9)dfs2(i);
    printf("%d\n",ans);
    return 0;
}
</source_code>
